assets/theme.css:
/* Aurora — EcomStrait Liquid theme. Colors/fonts/radius come from theme settings. */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;font-family:var(--font-body);color:var(--ink);background:var(--bg);line-height:1.55;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block;object-fit:cover}
a{color:inherit;text-decoration:none}
h1,h2,h3{font-family:var(--font-heading);line-height:1.15;margin:0}
.muted{color:#64748b}
.container{width:100%;max-width:1200px;margin:0 auto;padding:0 20px}
.section{padding:56px 0}
.section--narrow{max-width:760px;margin:0 auto}
.section-title{font-size:clamp(1.6rem,3vw,2.2rem);font-weight:800;letter-spacing:-.02em}
.section-head{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin-bottom:24px}
.link-more{color:var(--brand);font-weight:600;font-size:.9rem}

/* Buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;border:0;cursor:pointer;font-weight:700;font-size:.95rem;padding:.7rem 1.2rem;border-radius:var(--radius);transition:transform .05s ease,opacity .2s ease}
.btn:active{transform:translateY(1px)}
.btn-lg{padding:.9rem 1.6rem;font-size:1rem}
.btn-primary{background:var(--brand);color:#fff}
.btn-primary:hover{opacity:.92}
.btn-primary[disabled]{opacity:.5;cursor:not-allowed}
.btn-ghost{background:transparent;border:1px solid #e2e8f0;color:var(--ink)}

/* Header */
.site-header{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(10px);border-bottom:1px solid #eef2f7}
.site-header__inner{display:flex;align-items:center;justify-content:space-between;gap:24px;height:64px}
.site-header__name{font-family:var(--font-heading);font-weight:800;font-size:1.25rem}
.site-nav{display:flex;gap:22px}
.site-nav__link{font-size:.95rem;font-weight:600;color:#475569}
.site-nav__link:hover,.site-nav__link.is-active{color:var(--ink)}
.site-header__cart{font-weight:700;font-size:.9rem}
.cart-count{display:inline-grid;place-items:center;min-width:20px;height:20px;padding:0 6px;border-radius:999px;background:var(--brand);color:#fff;font-size:.72rem}
@media (max-width:640px){.site-nav{display:none}}

/* Hero */
.hero{background:linear-gradient(120deg,var(--brand),var(--accent));color:#fff;background-size:cover;background-position:center}
.hero__inner{padding:96px 20px;text-align:center;max-width:760px;margin:0 auto}
.hero__heading{font-size:clamp(2rem,5vw,3.4rem);font-weight:800;letter-spacing:-.03em}
.hero__subheading{font-size:clamp(1rem,2vw,1.2rem);opacity:.92;margin:16px 0 28px}
.hero--image .hero__inner{padding:128px 20px}

/* Grids */
.grid{display:grid;gap:20px}
.grid-products{grid-template-columns:repeat(2,1fr)}
.grid-collections{grid-template-columns:repeat(2,1fr)}
.grid-3{grid-template-columns:repeat(3,1fr)}
@media (min-width:720px){.grid-products{grid-template-columns:repeat(4,1fr)}.grid-collections{grid-template-columns:repeat(3,1fr)}}
@media (max-width:640px){.grid-3{grid-template-columns:1fr}}

/* Product card */
.product-card{display:flex;flex-direction:column;overflow:hidden;background:#fff;border:1px solid #eef2f7}
.product-card:hover{box-shadow:0 8px 30px rgba(2,6,23,.08)}
.product-card__media{position:relative;aspect-ratio:1/1;background:#f1f5f9}
.product-card__placeholder,.product-card--placeholder{aspect-ratio:1/1;background:linear-gradient(120deg,#eef2f7,#e2e8f0)}
.product-card__body{padding:12px 14px;display:flex;flex-direction:column;gap:4px}
.product-card__title{font-weight:600;font-size:.95rem}
.product-card__price{font-weight:800;color:var(--ink)}
.badge{position:absolute;top:10px;left:10px;padding:3px 8px;border-radius:999px;font-size:.72rem;font-weight:700}
.badge--soldout{background:#0f172a;color:#fff}

/* Product page */
.product{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:start}
@media (max-width:820px){.product{grid-template-columns:1fr}}
.product__title{font-size:clamp(1.6rem,3vw,2.4rem);font-weight:800;letter-spacing:-.02em}
.product__price{font-size:1.4rem;font-weight:800;margin:12px 0 20px}
.product__options{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:18px}
.product__option{display:flex;flex-direction:column;gap:6px;font-size:.85rem;font-weight:600}
.product__option select{padding:.55rem .7rem;border:1px solid #e2e8f0;border-radius:var(--radius)}
.product__description{margin-top:24px}
.product__media-placeholder{aspect-ratio:1/1;background:linear-gradient(120deg,#eef2f7,#e2e8f0)}

/* Value props */
.value-prop{padding:24px;border:1px solid #eef2f7;border-radius:var(--radius)}
.value-prop__title{font-size:1.05rem;font-weight:700;margin-bottom:6px}

/* Cart */
.cart-line{display:grid;grid-template-columns:80px 1fr auto auto;gap:16px;align-items:center;padding:16px 0;border-bottom:1px solid #eef2f7}
.cart-line__title{font-weight:600}
.cart-line__qty{width:64px;padding:.5rem;border:1px solid #e2e8f0;border-radius:var(--radius)}
.cart-footer{display:flex;flex-wrap:wrap;justify-content:space-between;gap:16px;align-items:center;padding-top:20px}
.cart-subtotal{font-size:1.2rem}
.cart-actions{display:flex;gap:12px}

/* Collections */
.collection-card{position:relative;display:block;overflow:hidden;border:1px solid #eef2f7}
.collection-card__title{position:absolute;left:14px;bottom:14px;background:rgba(255,255,255,.9);padding:6px 12px;border-radius:999px;font-weight:700}
.collection-head{margin-bottom:24px}

/* Misc */
.rte a{color:var(--brand);text-decoration:underline}
.pagination{display:flex;gap:10px;justify-content:center;margin-top:32px;font-weight:600}
.pagination .is-current{color:var(--brand)}
.search-form{display:flex;gap:10px;margin:16px 0 28px}
.search-form input{flex:1;padding:.7rem 1rem;border:1px solid #e2e8f0;border-radius:var(--radius)}

/* Footer */
.site-footer{margin-top:40px;border-top:1px solid #eef2f7;padding:40px 0 24px}
.site-footer__inner{display:flex;flex-wrap:wrap;justify-content:space-between;gap:24px}
.site-footer__name{font-family:var(--font-heading);font-weight:800;font-size:1.1rem;margin:0 0 4px}
.site-footer__nav{display:flex;flex-direction:column;gap:8px}
.site-footer__legal{margin-top:24px;font-size:.85rem}

@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}

